# Language dimensions: (id, group, name, regex or None(special), definition, do, dont)
import re
D=[]
def add(g,n,rx,defn,do,dont,scope='word'): D.append(dict(id=len(D)+1,group=g,name=n,rx=rx,defn=defn,do=do,dont=dont,scope=scope))
# Sentence shape (special computed)
for n,dfn in [('Mean sentence length (words)','Average words per sentence in host narration.'),
 ('Median sentence length','Middle sentence length; less skewed by caption run-ons.'),
 ('Sentence-length spread (SD)','Burstiness. Human speech mixes 3-word punches with 35-word run-ons.'),
 ('Short sentences (<=6 words) %','Share of punch lines and fragments.'),
 ('Long sentences (>=30 words) %','Share of breathless run-on sentences.'),
 ('Fragments (no verb-ish word) %','Verbless fragments such as "Two weeks." or "Not great."'),
 ('Questions %','Share of sentences ending in ?'),
 ('Exclamations %','Share of sentences ending in !')]:
    add('Sentence shape',n,None,dfn,'Match the target band from the weighted table.','Do not flatten every sentence to 15-20 words (AI uniformity).','special')
# Openers
for w,dfn in [('So','Sentence-initial So: the spoken pivot into consequence or the next beat.'),('And','Sentence-initial And: chaining story beats like speech.'),('But','Sentence-initial But: turn or complication.'),('Now','Sentence-initial Now: time/turn marker.'),('Because','Sentence-initial Because: fragment answer to a question.'),('Like','Sentence-initial Like: spoken lead-in, framing a clip or example.'),('Which','Sentence-initial Which (means/is why): consequence fragment.'),('This','Sentence-initial This: pointing at what is on screen or just said.'),('It','Sentence-initial It.'),('The','Sentence-initial The.'),('I','Sentence-initial I: narrator self-insert.'),('You','Sentence-initial You: direct viewer address.'),('We','Sentence-initial We.'),('And so','Sentence-initial And so.'),('Well','Sentence-initial Well.'),('Okay/OK','Sentence-initial Okay/OK.'),('Look','Sentence-initial Look: Gen-heavy attention grab.'),('Honestly','Sentence-initial Honestly.'),('In/On (date/place)','Sentence-initial In/On: scene and date setters.')]:
    pat={'Okay/OK':r'^(?:okay|ok)\b','In/On (date/place)':r'^(?:in|on)\b','And so':r'^and so\b'}.get(w, r'^'+w.lower()+r'\b')
    add('Openers','Opener: '+w,pat,dfn,'Use at the weighted rate; vary it.','Do not open with Moreover/Furthermore/Additionally instead.','opener')
# Fillers/hedges
for n,rx,dfn in [('just',r'\bjust\b','Minimizer/intensifier "just".'),('really',r'\breally\b','Intensifier "really".'),('actually',r'\bactually\b','Correction marker "actually".'),('basically',r'\bbasically\b','Simplifier "basically".'),('literally',r'\bliterally\b','Emphasis "literally".'),('like (filler)',r'(?:,\s*like,|\blike,|\bit\'s like\b|\bwas like\b|\bjust like\b)','Spoken "like".'),('kind of',r'\bkind of\b','Hedge "kind of".'),('sort of',r'\bsort of\b','Hedge "sort of".'),('you know',r'\byou know\b(?! what| how| that| who| why)','Discourse marker "you know".'),('I think',r'\bi think\b','Narrator opinion hedge.'),('I mean',r'\bi mean\b','Self-repair "I mean".'),('honestly',r'\bhonestly\b','Candor marker.'),('probably',r'\bprobably\b','Probability hedge.'),('pretty (much/adv)',r'\bpretty (?:much|[a-z]+ly|good|bad|big|wild|crazy|clear|simple)\b','Softener "pretty X".'),('a lot',r'\ba lot\b','Casual quantity "a lot".'),('a bunch',r'\ba bunch of\b','Casual quantity "a bunch of".'),('right? tag',r'\bright\?','Tag question "right?".'),('obviously',r'\bobviously\b','Shared-knowledge marker.'),('apparently',r'\bapparently\b','Reported-hearsay marker.'),('exactly',r'\bexactly\b','Emphasis/precision "exactly".')]:
    add('Fillers and hedges',n,rx,dfn,'Keep at corpus rate; fillers are what make it sound spoken.','Do not strip all of them (reads as essay) or stack 3 in one sentence.')
# Connective logic
for n,rx,dfn in [('which means',r'\bwhich means\b','Consequence cascade.'),('in other words',r'\bin other words\b','Re-explaining in plain terms.'),('that means',r'\bthat means\b','Consequence.'),('the thing is / here\'s the thing',r'\b(?:the thing is|here\'s the thing)\b','Pivot to the real point.'),('turns out',r'\bturns? out\b','Reveal marker.'),('the problem is',r'\bthe (?:problem|issue|catch) (?:is|was)\b','Complication marker.'),('because (mid)',r'\bbecause\b','Causal glue.'),('so (mid-sentence)',r'[a-z,] so\b','Mid-sentence so.'),('but (any)',r'\bbut\b','Contrast density.'),('and then',r'\band then\b','Narrative sequencing.'),('even though',r'\beven though\b','Concession.'),('not just X but',r'\bnot (?:just|only)\b','Escalation frame.'),('instead',r'\binstead\b','Contrast.'),('meanwhile',r'\bmeanwhile\b','Parallel thread.'),('at the same time',r'\bat the same time\b','Parallel thread.')]:
    add('Connective logic',n,rx,dfn,'Chain with spoken connectors.','Avoid essay connectors (Moreover, Furthermore, Thus, Hence, Consequently).')
# Viewer address and persona
for n,rx,dfn in [('you/your',r'\b(?:you|your|you\'re|yourself)\b','Second-person density.'),('I/me/my',r'\b(?:i|me|my|i\'m|i\'ve|i\'d)\b','Narrator first person.'),('we/us/our',r'\b(?:we|us|our|we\'re|we\'ve)\b','Inclusive or team "we".'),('imagine',r'\bimagine\b','Viewer simulation.'),('let\'s / let me',r'\blet(?:\'s| me| us)\b','Guiding the viewer.'),('if you\'re wondering / you might',r'\b(?:if you\'re|you might|you may|you probably)\b','Anticipating viewer thought.'),('think about it',r'\bthink about (?:it|that|this)\b','Prompting reflection.')]:
    add('Address and persona',n,rx,dfn,'Talk to one viewer.','No "dear viewers", no "in this video we will explore".')
# Register
for n,rx,dfn in [('contractions',r"\b\w+'(?:s|re|ve|ll|d|t|m)\b",'Contractions per 1k words.'),('swearing',r'\b(?:hell|damn|shit|fuck\w*|ass|crap|bullshit)\b','Profanity.'),('slang (cooked/insane/crazy/wild/huge)',r'\b(?:cooked|insane|crazy|wild|huge|massive|absurd|ridiculous|nuts)\b','Casual hyperbole.'),('gonna/wanna/gotta',r'\b(?:gonna|wanna|gotta|kinda|sorta)\b','Phonetic contractions.'),('guy/guys/dude',r'\b(?:guy|guys|dude|folks)\b','Casual people words.'),('stuff/thing(s)',r'\b(?:stuff|things?)\b','Vague nouns.'),('AI-tell vocabulary',r'\b(?:delve|tapestry|testament|landscape|crucial|pivotal|robust|leverage|seamless|multifaceted|intricate|realm|underscore|showcase|foster|vibrant|navigate|ever-evolving|game-changer|unlock|elevate)\b','Words that flag machine text.'),('essay connectors',r'\b(?:moreover|furthermore|additionally|consequently|thus|hence|nevertheless|in conclusion|notably)\b','Formal transitions.')]:
    add('Register',n,rx,dfn,'Stay conversational at corpus rates.','Never use AI-tell vocabulary or essay connectors in narration.')
# Numbers and specificity
for n,rx,dfn in [('numerals',r'\b\d[\d,\.]*\b','Digits per 1k.'),('money',r'\$\d|\b\d[\d,\.]* (?:dollars|million|billion|trillion)\b','Money amounts.'),('percent',r'\d+ ?%|\bpercent\b','Percentages.'),('years',r'\b(?:19|20)\d\d\b','Explicit years.'),('big-unit words',r'\b(?:million|billion|trillion)\b','Scale words.'),('named months/days',r'\b(?:january|february|march|april|may|june|july|august|september|october|november|december|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b','Dated precision.')]:
    add('Specificity',n,rx,dfn,'Anchor claims in exact numbers.','No "a significant amount", "numerous", "various".')
# Punctuation
for n,rx,dfn in [('em/en dashes',r'[—–]| - ','Dashes.'),('semicolons',r';','Semicolons.'),('colons',r':','Colons.'),('quotes marks',r'["“”]','Quoted speech.'),('ellipses',r'\.\.\.|…','Trailing off.')]:
    add('Punctuation',n,rx,dfn,'Commas and periods carry the rhythm.','Avoid semicolons and em-dash chains (AI tells in spoken scripts).')
# Rhetorical moves (sentence)
for n,rx,dfn in [('rhetorical question then answer',r'\?$','Question sentences (often answered next line).'),('"this is" pointing',r'^this is\b','"This is X" pointing at footage or a person.'),('"what" cleft / what no one',r'\bwhat (?:no one|nobody|most people|people)\b','"What no one is talking about".'),('"the reason"',r'\bthe (?:real )?reason\b','Explanation frame.'),('"not because ... but because"',r'\bnot because\b','Contrast of causes.'),('"here\'s" presenter',r'^here\'s\b','"Here\'s X" presenter line.'),('"the answer is"',r'\bthe answer (?:is|was)\b','Answer frame.'),('rule of three lists',r'\b\w+, \w+(?:,)? and \w+\b','Triplets (watch for AI over-use).')]:
    add('Rhetorical moves',n,rx,dfn,'Use as spoken devices, not decoration.','Do not end every paragraph with a triplet or a "not X, but Y" flourish.','sent' if n.startswith(('"this','"here')) else 'word')
